// ===== lang ==================================================================
// Which language the mod's messages are in, shared by hooks/register.js and hooks/compact-flow.mjs.
// The state lives here (one set per Claude Code session, put back by resetLang) so both files speak
// the same language. A mod's analyser follows `$` only into function declarations, so these are
// declarations, not injected callbacks.
const VOTES_KEPT = 5
const votes = []
let settingPromise
let storedPromise
let storedLang

function resetLang() {
  settingPromise = undefined
  storedPromise = undefined
  storedLang = undefined
  votes.length = 0
}

// The language of one typed prompt ('tr', 'en'); the last few decide the session's language.
function addLanguageVote(verdict) {
  votes.push(verdict)
  if (votes.length > VOTES_KEPT) votes.shift()
}

async function loadLanguageSetting($) {
  try {
    const settings = await $.settings.read()
    return typeof settings.language === 'string' ? settings.language : undefined
  } catch (err) {
    // No settings to read: the other signals still decide.
    return undefined
  }
}

async function loadStoredLanguage($) {
  try {
    const value = await $.store.get('lang')
    return value === 'tr' || value === 'en' ? value : undefined
  } catch (err) {
    // No store: the language is simply not remembered.
    return undefined
  }
}

// The language of the messages. Cheap to call: the settings and the stored language are read once
// per session (the promises are kept, so two overlapping calls share one read), and a language
// read off the prompts is remembered (that one word, "tr" or "en") so the next session can ask its
// first question in it, before any prompt has been typed.
async function resolveLang($) {
  const override = await $.env.get('CREW_CHIEF_LANG')
  const locale = await $.env.get('LANG')
  if (settingPromise === undefined) settingPromise = loadLanguageSetting($)
  if (storedPromise === undefined) storedPromise = loadStoredLanguage($)
  const setting = await settingPromise
  if (storedLang === undefined) storedLang = await storedPromise
  const pick = pickLanguage({ override, setting, votes, stored: storedLang, locale })
  if (pick.source === 'prompts' && pick.lang !== storedLang) {
    storedLang = pick.lang
    try {
      await $.store.set('lang', pick.lang)
    } catch (err) {
      // Not remembered; it is detected again next time.
    }
  }
  return pick.lang
}

// ===== ask ===================================================================
// crew-chief questions with a deadline. Part of the mod in hooks/register.js (Claude Code 2.1.287+).
//
// $.ui.ask has no timeout, so a question nobody answers (a long job left running overnight) would stay open
// for good. Every question the mod asks goes through askWithDeadline, which notes the question's text here.
// $.ui.ask opens the dialog as a tool.call of AskUserQuestion that this mod's own hooks see; the hook below
// races that call against a timer, and when the timer wins it returns the flow's safe default as the
// answer: the engine closes the dialog and $.ui.ask resolves to that label, exactly as if it was clicked.
// (That hook is only reached while the asking hook still runs; see askWithDeadline for the other case.)
// Only questions noted here are raced: an AskUserQuestion that Claude raises itself passes through.
// CREW_CHIEF_ASK_TIMEOUT_MIN sets the minutes (default 20, at most 30; "off" or "0" = no deadline).
// question text -> { fallback, ms, lang, announced }
const deadlines = new Map()
const EXPIRED = Symbol('expired')

// Asks like $.ui.ask (same answer, same rejection when dismissed or when nobody can be asked), but an
// unanswered question resolves to `fallback` after the deadline. Two things enforce it:
//   - the sibling hook in registerAsk closes the dialog with that answer. It is only reached while the
//     hook that asks is still running (a $ call made after its hook returned skips this mod's own hooks);
//   - the race below, so the flow moves on with the default in every case, even when the dialog could
//     not be closed (then a late click on it changes nothing).
async function askWithDeadline($, question, answers, fallback) {
  let entry
  try {
    const ms = parseAskTimeout(await $.env.get('CREW_CHIEF_ASK_TIMEOUT_MIN'))
    const label = pickFallback(answers, fallback)
    if (ms > 0 && label === undefined) {
      $.ui.log('crew-chief: no safe default for a question, it has no deadline: ' + String(fallback), { to: 'debug' })
    }
    if (ms > 0 && label !== undefined) {
      // Two questions with the same text at once share the first one's entry.
      entry = deadlines.get(question) ?? { fallback: label, ms, lang: await resolveLang($), question, announced: false }
    }
  } catch (err) {
    entry = undefined // no deadline then; the question itself still goes out
  }
  if (entry === undefined) return $.ui.ask(question, answers)
  const owner = !deadlines.has(question)
  if (owner) deadlines.set(question, entry)
  let timer
  try {
    const asked = $.ui.ask(question, answers)
    asked.catch(() => {}) // dismissed after the deadline: nobody is listening any more
    const expired = new Promise((resolve) => {
      timer = $.clock.after(entry.ms, () => resolve(EXPIRED))
    })
    const first = await Promise.race([asked, expired])
    if (first !== EXPIRED) return first
    announceExpiry($, entry)
    return entry.fallback
  } finally {
    try {
      if (timer) timer.cancel()
    } catch (err) {
      // Already fired.
    }
    if (owner && deadlines.get(question) === entry) deadlines.delete(question)
  }
}

function deadlineFor(e) {
  const qs = Array.isArray(e.questions) ? e.questions : []
  if (qs.length !== 1 || !qs[0] || typeof qs[0].question !== 'string') return undefined
  return deadlines.get(qs[0].question)
}

// Once per question, whichever of the two deadlines comes first.
function announceExpiry($, d) {
  if (d.announced) return
  d.announced = true
  try {
    const min = minutesLabel(d.ms)
    $.ui.log('crew-chief: question unanswered for ' + min + ' min, answered "' + d.fallback + '": ' + d.question.slice(0, 120), { to: 'debug' })
    $.ui.toast(t(d.lang, 'ask_expired_toast', { min, answer: d.fallback }), { timeoutMs: 15000 })
  } catch (err) {
    // The default answer stands either way.
  }
}

function registerAsk(on) {
  on('tool.call', { tool: 'AskUserQuestion' }, async ($, e, next) => {
    let d
    try {
      d = deadlineFor(e)
    } catch (err) {
      d = undefined
    }
    if (d === undefined) return next(e)
    let timer
    let answered
    try {
      const expired = new Promise((resolve) => {
        timer = $.clock.after(d.ms, () => resolve(EXPIRED))
      })
      answered = next(e)
      answered.catch(() => {})
      const first = await Promise.race([answered.then((r) => ({ r })), expired])
      if (first === EXPIRED) {
        announceExpiry($, d)
        return { result: { questions: e.questions, answers: { [d.question]: d.fallback }, afkTimeoutMs: d.ms } }
      }
      return first.r
    } catch (err) {
      // A dismissed dialog rejects `answered`: pass that on unchanged. Anything else: no deadline.
      return answered !== undefined ? answered : next(e)
    } finally {
      try {
        if (timer) timer.cancel()
      } catch (err) {
        // Already fired.
      }
    }
  })
}

// ===== handoff ===============================================================
// Finds the project's handoff files (see skills/crew-handoff) for the compact flow and /crew-tidy.
// The lookup order matches scripts/compact-restore.sh: STATUS.md (or durum.md) next to the working
// directory, then at the repository root, then one level down. A mod's analyser follows `$` only into
// function declarations, so this is one, shared by the files that need it.

// Shared by every part of the bundle: a call that may throw, with a fallback value.
async function safe(fn, fallback) {
  try {
    return await fn()
  } catch (err) {
    return fallback
  }
}

async function findHandoff($) {
  const cwd = await safe(() => $.session.cwd(), undefined)
  if (!cwd) return undefined
  const root = (await safe(() => $.session.root(), cwd)) || cwd
  const dirs = [...new Set([cwd, root])]
  const names = ['STATUS.md', 'durum.md']
  let dir
  let status
  for (const d of dirs) {
    for (const n of names) {
      if (!status && (await safe(() => $.fs.exists(`${d}/${n}`), false))) {
        dir = d
        status = `${d}/${n}`
      }
    }
  }
  if (!status) {
    const entries = await safe(() => $.fs.list(root), [])
    for (const entry of entries) {
      if (status || entry.kind !== 'dir' || entry.name.startsWith('.') || entry.name === 'node_modules') continue
      for (const n of names) {
        if (!status && (await safe(() => $.fs.exists(`${root}/${entry.name}/${n}`), false))) {
          dir = `${root}/${entry.name}`
          status = `${dir}/${n}`
        }
      }
    }
  }
  let tasks
  for (const d of [dir, cwd, root]) {
    if (!tasks && d && (await safe(() => $.fs.exists(`${d}/tasks.json`), false))) tasks = `${d}/tasks.json`
  }
  let progress
  if (dir) {
    for (const n of ['PROGRESS.md', 'ilerleme.md']) {
      if (!progress && (await safe(() => $.fs.exists(`${dir}/${n}`), false))) progress = `${dir}/${n}`
    }
  }
  if (!status && !tasks) return undefined
  return { dir, status, tasks, progress }
}

// ===== stats-flow ============================================================
// /crew-report and the cache-cooling hint. Part of the mod in hooks/register.js (Claude Code 2.1.287+).
//
//   /crew-report   tokens (exact) and cost (approximate) by role (main or subagent) and model, plus how
//                  much of the output came from subagents and from Sonnet or Haiku: whether the routing
//                  is moving work to cheaper tiers. Claude Code reports one session total, so each
//                  request is credited with what the total grew by since the previous one ended.
//   cache hint     a toast on your next prompt when the prompt cache has probably gone cold during an
//                  idle gap and the context is big, because that message re-reads it at the full price.
//                  The cache lifetime is learned from the usage numbers (see report-logic.mjs); until an
//                  expiry has been seen nothing is warned. CREW_CHIEF_CACHE_HINT=off turns it off.
// Nothing is written outside the plugin's store (the learned gap lengths). Nothing leaves the machine.
function freshStats() {
  return { stats: newStats(), lastCost: undefined, lastMainEndAt: undefined, lastMainContext: 0, stepGap: undefined, hint: undefined, warnedFor: undefined }
}

let sf = freshStats()

async function loadHint($) {
  if (sf.hint !== undefined) return sf.hint
  const text = await safe(() => $.store.get('cache_hint'), undefined)
  sf.hint = typeof text === 'string' ? parseHint(text) : {}
  return sf.hint
}

async function statsSessionStart($) {
  sf = freshStats()
  try {
    await $.command.register({
      name: 'crew-report',
      description: t(await resolveLang($), 'cmd_report_description'),
      argumentHint: '',
    })
  } catch (err) {
    // The name is taken: the rest still works.
  }
}

function statsReset() {
  sf = freshStats()
}

// A compaction (or any change of conversation) guarantees a cache miss on the next request: that gap
// must not be mistaken for the cache's lifetime.
function statsNoteBoundary() {
  sf.lastMainEndAt = undefined
  sf.stepGap = undefined
}

// Before a request goes out: how long the main conversation sat idle since its last one.
async function statsStepStart($, e) {
  if (e.agentId !== undefined) return
  const now = await $.clock.now()
  sf.stepGap = sf.lastMainEndAt === undefined ? undefined : now - sf.lastMainEndAt
}

// After a request: add it to the tallies, and learn from it how long the cache lives.
async function statsStepEnd($, e, result) {
  try {
    const main = e.agentId === undefined
    const usage = result?.usage ?? undefined
    const family = modelFamily(usage?.model ?? e.model)
    const now = await $.clock.now()
    const cost = await safe(() => $.session.usage(), undefined)
    const usd = cost?.cost?.usd
    // The total starts at 0 and falls back to 0 after /clear: a drop means a freshStats total, all of it new.
    let grew
    if (typeof usd === 'number') {
      const base = sf.lastCost ?? 0
      grew = usd >= base ? usd - base : usd
      sf.lastCost = usd
    }
    addStep(sf.stats, { role: main ? 'main' : 'subagent', family, usage, usd: grew })
    if (main && usage) {
      const input = Number(usage.input_tokens) || 0
      const cacheRead = Number(usage.cache_read_input_tokens) || 0
      const cacheWrite = Number(usage.cache_creation_input_tokens) || 0
      const verdict = classifyGap({ gapMs: sf.stepGap, input, cacheRead, cacheWrite })
      if (verdict !== undefined) {
        const hint = nextHint(await loadHint($), sf.stepGap, verdict)
        sf.hint = hint
        await safe(() => $.store.set('cache_hint', JSON.stringify(hint)), undefined)
      }
      sf.lastMainContext = input + cacheRead + cacheWrite
    }
    if (main) sf.lastMainEndAt = now
  } catch (err) {
    // The tallies are a convenience; never get in the way of a request.
  }
}

// On a typed prompt: warn once per idle gap if the cache has probably gone cold.
async function cacheOnPrompt($) {
  try {
    if ((await safe(() => $.env.get('CREW_CHIEF_CACHE_HINT'), undefined)) === 'off') return
    if (sf.lastMainEndAt === undefined || sf.warnedFor === sf.lastMainEndAt) return
    const now = await $.clock.now()
    const gap = now - sf.lastMainEndAt
    if (!shouldWarnCold(await loadHint($), gap, sf.lastMainContext)) return
    sf.warnedFor = sf.lastMainEndAt
    const lang = await resolveLang($)
    $.ui.toast(t(lang, 'cache_cold', { idle: formatDuration(gap, unitsFor(lang)), tokens: fmtTokens(sf.lastMainContext) }), { timeoutMs: 12000 })
  } catch (err) {
    // A missing hint is better than a broken prompt.
  }
}

async function buildStatsReport($) {
  const lang = await resolveLang($)
  const rows = statsRows(sf.stats)
  if (rows.length === 0) return t(lang, 'report_none')
  const out = [t(lang, 'report_title')]
  for (const r of rows) {
    out.push(
      '- ' +
        t(lang, 'report_row', {
          role: t(lang, r.role === 'main' ? 'role_main' : 'role_subagent'),
          model: r.family,
          requests: r.requests,
          input: fmtTokens(r.input),
          cacheRead: fmtTokens(r.cacheRead),
          cacheWrite: fmtTokens(r.cacheWrite),
          output: fmtTokens(r.output),
          usd: fmtUsd(r.usd),
        }),
    )
  }
  const total = await safe(() => $.session.usage(), undefined)
  if (typeof total?.cost?.usd === 'number') out.push(t(lang, 'report_total', { usd: fmtUsd(total.cost.usd) }))
  const share = routingShare(rows)
  if (share.total > 0) out.push(t(lang, 'report_share', { sub: share.subagent, cheaper: share.cheaper }))
  out.push(t(lang, 'report_note'))
  return out.join('\n')
}

function registerStats(on) {
  on('command.run', { command: 'crew-report' }, async ($) => ({ text: await buildStatsReport($) }))
}

// ===== reset-flow ============================================================
// crew-chief reset flow: tells you when a plan limit you were close to has reset, and, when a limit
// actually stops Claude, offers to send "continue" for you at the moment it resets. Part of the mod in
// hooks/register.js.
//
//   - Measurements only arrive after a response, so nothing would wake an idle session when a window
//     rolls over. A timer is set for each window that was close to full (90 % or more) and is due to
//     reset within 12 hours; it fires a toast at the reset time.
//   - A limit that really stops a turn arrives as the StopFailure event with error "rate_limit" (not the
//     100 % mark: with usage credits you keep working past it). Then the person is asked whether to
//     send "continue" at the reset. Only on a yes, only for a reset within 6 hours, and never if the
//     person typed something in the meantime. The message says who sent it (it is not sent as the
//     person's own words).
// CREW_CHIEF_RESET=off turns both off. Timers last as long as the session does.
const NEAR_FULL_PERCENT = 90
const TOAST_HORIZON_MS = 12 * 60 * 60 * 1000
const CONTINUE_HORIZON_MS = 6 * 60 * 60 * 1000
const BUFFER_MS = 15_000

const CONTINUE_TEXT =
  'crew-chief: the usage limit has reset, as the user asked in advance. Continue where you left off, with the same task.'

let generation = 0

function freshReset() {
  return { scheduled: new Set(), planned: new Set(), never: false, asking: false, lastPromptAt: 0 }
}

let rf = freshReset()

// A timer set before /clear or a new session must not act in the next one: each carries the generation
// it was set in.
function resetResetFlow() {
  rf = freshReset()
  generation += 1
  open.reset = false
}

function resetNotePrompt(now) {
  rf.lastPromptAt = now
}

async function off($) {
  try {
    return (await $.env.get('CREW_CHIEF_RESET')) === 'off'
  } catch (err) {
    return false
  }
}

function resetMs(window) {
  const at = typeof window.resetsAt === 'string' ? Date.parse(window.resetsAt) : NaN
  return Number.isFinite(at) ? at : undefined
}

// Called with each usage reading. Sets one timer per (window, reset time) for a window that is close
// to full and resets soon; the toast comes when the window rolls over, even if the session is idle.
async function resetOnUsage($, usage) {
  if (await off($)) return
  const now = await $.clock.now()
  for (const w of usage?.rateLimits ?? []) {
    if (w.kind !== 'five_hour' && w.kind !== 'seven_day') continue
    const at = resetMs(w)
    if (at === undefined || w.percentUsed < NEAR_FULL_PERCENT) continue
    const wait = at - now
    const key = w.kind + '|' + at
    if (wait <= 0 || wait > TOAST_HORIZON_MS || rf.scheduled.has(key)) continue
    rf.scheduled.add(key)
    const born = generation
    $.clock.after(wait + BUFFER_MS, () => (born === generation ? announceReset($, w.kind) : undefined))
  }
}

async function announceReset($, kind) {
  if (await off($)) return
  const lang = await resolveLang($)
  $.ui.toast(t(lang, 'reset_toast', { window: windowName(lang, kind) }), { timeoutMs: 15000 })
}

// The window that stopped the turn: the fullest one that has a reset time in the future.
function blockingWindow(usage, now) {
  let best
  for (const w of usage?.rateLimits ?? []) {
    const at = resetMs(w)
    if (at === undefined || at <= now) continue
    if (best === undefined || w.percentUsed > best.window.percentUsed) best = { window: w, at }
  }
  return best
}

async function offerContinue($) {
  if (rf.asking || open.saver || open.compact || open.reset) return
  const now = await $.clock.now()
  const usage = await $.session.usage()
  const hit = blockingWindow(usage, now)
  if (!hit) return
  const wait = hit.at - now
  const key = hit.window.kind + '|' + hit.at
  if (wait > CONTINUE_HORIZON_MS || rf.planned.has(key) || rf.never) return
  rf.asking = true
  open.reset = true
  try {
    const lang = await resolveLang($)
    const answers = [t(lang, 'limit_yes'), t(lang, 'limit_no'), t(lang, 'limit_never')]
    let answer
    try {
      answer = await askWithDeadline(
        $,
        t(lang, 'limit_ask', { window: windowName(lang, hit.window.kind), duration: formatDuration(wait, unitsFor(lang)) }),
        answers,
        answers[1],
      )
    } catch (err) {
      return
    }
    if (answer === answers[2]) {
      rf.never = true
    } else if (answer === answers[0]) {
      rf.planned.add(key)
      const askedAt = now
      const born = generation
      $.clock.after(wait + BUFFER_MS, () => (born === generation ? sendContinue($, askedAt, hit.window.kind) : undefined))
    }
  } finally {
    rf.asking = false
    open.reset = false
  }
}

async function sendContinue($, askedAt, kind) {
  if (await off($)) return
  if (rf.lastPromptAt > askedAt) return // the person is back and typing: leave it to them
  try {
    $.prompt.submit({ text: CONTINUE_TEXT }).catch(() => {})
    const lang = await resolveLang($)
    $.ui.toast(t(lang, 'limit_continue_toast', { window: windowName(lang, kind) }), { timeoutMs: 10000 })
  } catch (err) {
    // The session cannot take a prompt right now; nothing more to do.
  }
}

function registerReset(on) {
  // StopFailure: a turn ended on an error. Only a rate limit matters here. (Settings-hook events do not
  // reach a mod where an organization manages Claude Code; then the offer simply never comes.)
  on('classic.StopFailure', async ($, e, next) => {
    if (e.error === 'rate_limit' && !(await off($))) offerContinue($) // not awaited: the hook must not wait
    return next(e)
  })
}

// ===== compact-flow ==========================================================
// crew-chief compact flow: gets a long conversation compacted at a good moment, with nothing important
// lost, and only after the person says yes. Part of the mod in hooks/register.js (Claude Code 2.1.287+).
//
// How it works (every step below was checked live on Claude Code 2.1.300, see CHANGELOG 0.6.0):
//   1. Past the "arm" size (250k tokens on a 1M window, 60 % of a small one) the next prompt carries a
//      one-time note telling Claude to call the tool crew_compact_checkpoint at the next natural phase
//      boundary (never mid-task). Claude decides when a phase is over.
//   2. The tool only takes note and returns at once (a tool that waited for the person would hold the turn
//      open, overnight if nobody is there). The person is asked after the turn has ended cleanly and the
//      session has stayed quiet for 10 seconds with no subagent running; otherwise at the next clean turn
//      end. If Claude never calls the tool, the same happens once the "ask" size is passed (400k, 85 % of
//      a small window). Nothing is compacted without a yes; an unanswered question counts as "not now".
//   3. On yes, Claude updates STATUS.md / tasks.json / PROGRESS.md (the handoff files, when the project
//      has them). Compaction waits until STATUS.md has changed (the gate) or the person overrides.
//   4. The compaction runs between turns with a detailed brief for the summarizer (compact-logic.mjs).
//      The same brief is added to a /compact the person types and to an automatic compaction.
//   5. After any compaction: the raw summary is saved, the summary is checked for the person's pinned
//      constraints and the open tasks, a toast says what was missing, and the transcript is checked for
//      lost lines. scripts/compact-restore.sh (SessionStart, compact) puts the pinned lines back.
// Environment: CREW_CHIEF_COMPACT=off turns the whole flow off; CREW_CHIEF_COMPACT_FOCUS=off only stops
// the brief being added to compactions; CREW_CHIEF_COMPACT_ARM / CREW_CHIEF_COMPACT_ASK set the sizes
// ("250k", "400k"). Nothing leaves the machine.
const TOOL_NAME = 'crew_compact_checkpoint'
const TOOL_MATCH = /^mcp__.+__crew_compact_checkpoint$/
const REARM_GROWTH_TOKENS = 100_000
const COMPACT_DELAY_MS = 1200
const RETRY_MS = 3000
const MAX_RETRIES = 3
const SUMMARIES_KEPT = 5
const TRANSCRIPTS_KEPT = 3
const MAX_UPDATE_RETRIES = 2
const AGENT_WAIT_MS = 5000
const MAX_AGENT_WAITS = 36
// How long the session must stay quiet after a clean turn end before the compaction question opens.
const GRACE_MS = 10_000
// `waiting` is a subagent held on background work it owns (a server it started), on a plan's approval or
// on another agent: none of these is work that a compaction would cut in half, and a subagent that left a
// dev server running stays `waiting` for as long as the server lives, so it must never hold a compaction back.
const RUNNING_STATES = ['pending', 'running']

const TOOL_DESCRIPTION =
  'Propose compacting the conversation. Call it once, and only when a note from crew-chief says the context is large AND you have just finished a phase (a task done, tests passing, before an unrelated area). Never call it in the middle of work. It returns at once; the user is asked after your turn ends. Do not wait for an answer and do not call it again.'

const UPDATE_TEXT =
  'Update the handoff files of this project now, for those that exist: STATUS.md (Now, Next, Constraints = every rule the user gave, copied verbatim; keep the lines already there and only add new ones, Decisions, Failed attempts), tasks.json (only status and evidence change), PROGRESS.md (one dated line). If STATUS.md has no Constraints section, do not invent one; say so in your reply. Do not start any new work. Finish with one short line; the conversation is compacted right after your turn ends.'

// A project with no handoff files has nowhere to pin the user's rules, so the person is offered them first
// (the crew-handoff skill shows a preview and creates only what is missing; it needs a yes of its own).
const SETUP_TEXT =
  'This project has no handoff files (STATUS.md, tasks.json, PROGRESS.md), so nothing would put the user\'s rules back after the compaction. Before it runs, ask the user once (AskUserQuestion) whether to set them up now: run the crew-chief:crew-handoff skill, which shows a preview and creates only what is missing. If they agree, run it, then copy every rule the user gave in this conversation, verbatim, under Constraints in STATUS.md. If they decline, do nothing more about it. Do not start any new work. Finish with one short line; the conversation is compacted right after your turn ends.'

async function updateText($) {
  return (await findHandoff($)) ? UPDATE_TEXT : SETUP_TEXT
}

const RESULTS = {
  noted: 'Noted. The user will be asked about compaction after this turn finishes. Do not wait for an answer; carry on and finish the turn normally. Do not call this tool again.',
  notNeeded: 'Not needed yet. Keep working; crew-chief will say when to propose a compaction.',
  busy: 'A compaction is already being arranged. Nothing more to do about it.',
}

function freshCompact(toolReady = false) {
  return {
    armed: false,
    nudged: false,
    never: false,
    asking: false,
    askedFallback: false,
    rearmAt: 0,
    plan: null,
    compacting: false,
    toolReady,
    bgTasks: [],
    wantAsk: null, // { phase } once the question is due at a quiet turn end
    askTimer: null, // the one pending grace timer
    activity: 0, // counts main-loop prompts and model requests
  }
}

let ck = freshCompact()

// session.start does not fire after /clear, so the tool registered at the start is still there: keep
// toolReady across a reset, and let compactSessionStart (a real start) decide it afresh.
function resetCompact() {
  cancelAskTimer()
  ck = freshCompact(ck.toolReady)
  open.compact = false
}

// Each compaction starts a freshCompact cycle: arm again at the arm size, note again, ask again, and no plan
// left over from before it.
function cycleDone() {
  ck.armed = false
  ck.nudged = false
  ck.askedFallback = false
  ck.rearmAt = 0
  ck.plan = null
  ck.wantAsk = null
  cancelAskTimer()
  statsNoteBoundary()
}

function cancelAskTimer() {
  const timer = ck.askTimer
  ck.askTimer = null
  try {
    if (timer) timer.cancel()
  } catch (err) {
    // Already fired.
  }
}

// Called from the mod's main-loop prompt.submit and turn.step hooks: something started after the turn
// ended, so the question waits for the next clean turn end.
function compactNoteActivity() {
  ck.activity += 1
}

// A mod must spell environment variable names as literals in $.env.get, so each switch is written out.
async function disabled($) {
  return (await safe(() => $.env.get('CREW_CHIEF_COMPACT'), undefined)) === 'off'
}

async function focusOff($) {
  return (await disabled($)) || (await safe(() => $.env.get('CREW_CHIEF_COMPACT_FOCUS'), undefined)) === 'off'
}

// ---- the project's handoff files ------------------------------------------------------------

async function mtimeOf($, path) {
  if (!path) return undefined
  const stat = await safe(() => $.fs.stat(path), undefined)
  return stat ? stat.mtimeMs : undefined
}

// The gate: the main handoff file has been written since the person approved. A project without
// handoff files has nothing to wait for.
async function gateSatisfied($, plan) {
  const h = await findHandoff($)
  if (!h) return true
  const main = h.status ?? h.tasks
  const changed = await mtimeOf($, main)
  return changed !== undefined && changed > plan.approvedAt
}

// ---- thresholds and the one-time note -------------------------------------------------------

async function limits($, usage) {
  const arm = parseTokens(await safe(() => $.env.get('CREW_CHIEF_COMPACT_ARM'), undefined))
  const ask = parseTokens(await safe(() => $.env.get('CREW_CHIEF_COMPACT_ASK'), undefined))
  return compactThresholds(usage?.context?.window, { arm, ask })
}

// Called after every measurement and finished turn. Arms the flow at the arm size; after a "not now"
// it arms again only once the context has grown by another 100k.
async function compactUpdate($, usage) {
  if (await disabled($)) return
  const tokens = usage?.context?.tokens
  if (typeof tokens !== 'number' || ck.never || ck.plan || ck.compacting) return
  const lim = await limits($, usage)
  if (!ck.armed && tokens >= Math.max(lim.arm, ck.rearmAt)) {
    ck.armed = true
    ck.nudged = false
    ck.askedFallback = false
  }
}

// The text added (once per arming) to the next prompt, or undefined.
async function compactNudge($) {
  if (!ck.armed || ck.nudged || ck.never || ck.plan || ck.compacting || !ck.toolReady) return undefined
  if (await disabled($)) return undefined
  ck.nudged = true
  const usage = await safe(() => $.session.usage(), undefined)
  const tokens = usage?.context?.tokens
  const name = `mcp__${$.plugin.name}__${TOOL_NAME}`
  return `[crew-chief] The context is about ${tokensLabel(tokens)} tokens; quality and cost both get worse from here. At the next natural phase boundary (a task finished, tests passing, before starting an unrelated area; never in the middle of work) call the tool ${name} once with a one-line phase summary. It returns at once and the user is asked after your turn ends; do not wait for an answer and do not call it again.`
}

// ---- asking and planning --------------------------------------------------------------------

// ---- what is running right now ---------------------------------------------------------------
// Subagents always end and bring a result back, so a compaction waits for them. A dev server or watcher
// left open in the background never ends and compaction does not touch it, so those only get shown (and
// named to the summarizer), never waited for. The processes come from the Stop event's background_tasks.

async function agentCounts($) {
  const list = await safe(() => $.agent.list(), [])
  return {
    running: list.filter((a) => RUNNING_STATES.includes(a.status)).length,
    waiting: list.filter((a) => a.status === 'waiting').length,
  }
}

async function runningAgents($) {
  return (await agentCounts($)).running
}

async function dirtyFiles($) {
  const r = await safe(() => $.process.run(['git', 'status', '--porcelain']), undefined)
  if (!r || r.exitCode !== 0) return undefined
  return r.stdout.split('\n').filter((line) => line.trim() !== '').length
}

function processNames() {
  return ck.bgTasks.map((task) => task.command || task.description || task.id).filter(Boolean)
}

// With the task id: after a compaction Claude no longer remembers the handles of background tasks it started
// (anthropics/claude-code#29193), so the summary should keep them.
function processHandles() {
  return ck.bgTasks.map((task) => (task.id ? task.id + ': ' : '') + (task.command || task.description || '')).filter(Boolean)
}

async function stateLine($, lang, agents, waiting) {
  const parts = [t(lang, 'ck_state_agents', { n: agents })]
  if (waiting > 0) parts.push(t(lang, 'ck_state_waiting', { n: waiting }))
  const names = processNames()
  if (names.length > 0) parts.push(t(lang, 'ck_state_shells', { n: names.length, list: names.slice(0, 3).map((n) => n.slice(0, 40)).join(', ') }))
  const dirty = await dirtyFiles($)
  if (dirty !== undefined) parts.push(t(lang, 'ck_state_dirty', { n: dirty }))
  return t(lang, 'ck_state', { parts: parts.join(', ') })
}

async function askAndPlan($, why) {
  if (ck.asking || open.saver || open.reset) return 'busy'
  const { running: agents, waiting } = await agentCounts($)
  if (agents > 0) return 'subagents'
  ck.asking = true
  open.compact = true
  try {
    const lang = await resolveLang($)
    const usage = await safe(() => $.session.usage(), undefined)
    const tokens = usage?.context?.tokens
    const answers = [t(lang, 'ck_yes'), t(lang, 'ck_later'), t(lang, 'ck_never')]
    const phase = why.phase ? t(lang, 'ck_phase', { phase: why.phase }) : ''
    const state = await stateLine($, lang, agents, waiting)
    let answer
    try {
      // Unanswered: "not now", the same as clicking it.
      answer = await askWithDeadline($, t(lang, 'ck_ask', { tokens: tokensLabel(tokens), phase, state }), answers, answers[1])
    } catch (err) {
      return 'unavailable'
    }
    if (answer === answers[0]) {
      ck.plan = { approvedAt: await $.clock.now(), retries: 0 }
      return 'approved'
    }
    if (answer === answers[2]) {
      ck.never = true
      return 'never'
    }
    ck.armed = false
    ck.rearmAt = (typeof tokens === 'number' ? tokens : 0) + REARM_GROWTH_TOKENS
    return 'declined'
  } finally {
    ck.asking = false
    open.compact = false
  }
}

// Asks Claude, in a new turn, to update the handoff files (the path with no tool call to answer).
async function requestStateUpdate($) {
  const text = 'crew-chief: the user approved compacting this conversation. ' + (await updateText($))
  $.prompt.submit({ text }).catch(() => {})
}

// After a clean turn end: wait GRACE_MS, then ask if nothing started meanwhile. At most one timer.
function scheduleAsk($) {
  if (ck.askTimer) return
  const cycle = ck
  const seen = ck.activity
  ck.askTimer = $.clock.after(GRACE_MS, () => {
    if (cycle !== ck) return // /clear, /resume or a new session since
    ck.askTimer = null
    return askAfterGrace($, seen)
  })
}

async function askAfterGrace($, seen) {
  const why = ck.wantAsk
  if (!why) return
  if (!ck.armed || ck.never || ck.plan || ck.compacting || (await disabled($))) {
    ck.wantAsk = null
    return
  }
  if (ck.activity !== seen) return // a new turn started: ask at its end instead
  const outcome = await askAndPlan($, why)
  // 'busy' (another question is open) and 'subagents' keep the request for the next clean turn end.
  if (outcome === 'busy' || outcome === 'subagents') return
  ck.wantAsk = null
  if (outcome === 'approved') requestStateUpdate($)
  // Dismissed, or nobody can be asked: the 400k fallback does not ask again in this cycle either.
  else if (outcome === 'unavailable') ck.askedFallback = true
}

async function advancePlan($) {
  const plan = ck.plan
  if (!plan || ck.asking || open.saver || open.reset) return
  if (await gateSatisfied($, plan)) {
    scheduleCompaction($)
    return
  }
  const lang = await resolveLang($)
  const answers = [t(lang, 'ck_gate_anyway'), t(lang, 'ck_gate_retry'), t(lang, 'ck_gate_cancel')]
  ck.asking = true
  open.compact = true
  let answer
  try {
    // Unanswered: "cancel", the same as clicking it.
    answer = await askWithDeadline($, t(lang, 'ck_gate_ask'), answers, answers[2])
  } catch (err) {
    answer = answers[2]
  } finally {
    ck.asking = false
    open.compact = false
  }
  if (answer === answers[0]) {
    scheduleCompaction($)
  } else if (answer === answers[1] && plan.retries < MAX_UPDATE_RETRIES) {
    plan.retries += 1
    requestStateUpdate($)
  } else {
    const usage = await safe(() => $.session.usage(), undefined)
    const tokens = usage?.context?.tokens
    ck.plan = null
    ck.armed = false
    ck.rearmAt = (typeof tokens === 'number' ? tokens : 0) + REARM_GROWTH_TOKENS
  }
}

// Called after each finished main turn.
// `reason` is how the turn ended. Only a turn that ended with an answer counts as a phase boundary: after an
// interrupt (Esc) the update may be half done, and after an error or a refusal nothing was finished.
async function compactTurnComplete($, usage, reason) {
  if (await disabled($)) return
  await compactUpdate($, usage)
  const clean = reason === undefined || reason === 'answer'
  if (ck.plan) {
    if (clean) await advancePlan($)
    return
  }
  if (!clean) return
  const tokens = usage?.context?.tokens
  if (!ck.armed || ck.never || ck.compacting || ck.asking) return
  if (!ck.wantAsk && !ck.askedFallback && typeof tokens === 'number' && tokens >= (await limits($, usage)).ask) {
    // Claude never called the tool: ask anyway, once per cycle.
    ck.askedFallback = true
    ck.wantAsk = {}
  }
  if (ck.wantAsk) scheduleAsk($) // the hook never waits for the person
}

// ---- running the compaction -----------------------------------------------------------------

function scheduleCompaction($) {
  ck.plan = null
  ck.compacting = true
  $.clock.after(COMPACT_DELAY_MS, () => runCompaction($, 0))
}

async function runCompaction($, attempt, waited = 0) {
  let retry = false
  // Subagents started since the approval would lose their place in a summary: wait until they are done.
  if ((await runningAgents($)) > 0) {
    if (waited < MAX_AGENT_WAITS) {
      $.clock.after(AGENT_WAIT_MS, () => runCompaction($, attempt, waited + 1))
    } else {
      ck.compacting = false
      await failed($, t(await resolveLang($), 'ck_agents_still'))
    }
    return
  }
  try {
    const before = await transcriptLines($)
    await copyTranscriptIfNeeded($)
    const args = (await focusOff($)) ? {} : { instructions: withFocus('', backgroundNote(processHandles())) }
    const result = await $.session.compact(args)
    if (result && result.skip) {
      await failed($, String(result.skip))
    } else if (result && result.messages) {
      cycleDone()
      await afterCompaction($, result, before)
    }
  } catch (err) {
    const message = String(err && err.message ? err.message : err)
    // Mostly "a turn is running" (compaction waits for a gap between turns); a headless run can never do it.
    if (attempt < MAX_RETRIES && !/headless|not available/i.test(message)) {
      retry = true
      $.clock.after(RETRY_MS, () => runCompaction($, attempt + 1))
    } else {
      await failed($, message)
    }
  } finally {
    if (!retry) ck.compacting = false
  }
}

async function failed($, reason) {
  const lang = await resolveLang($)
  $.ui.toast(t(lang, 'toast_compact_failed', { reason: reason.slice(0, 160) }), { timeoutMs: 12000 })
}

// ---- after a compaction ---------------------------------------------------------------------

async function dataDir($) {
  const fromEnv = await safe(() => $.env.get('CLAUDE_PLUGIN_DATA'), undefined)
  if (fromEnv) return fromEnv
  const home = await safe(() => $.env.get('HOME'), undefined)
  const derived = pluginDataDir($.plugin.root, home)
  if (derived) return derived
  const tmp = (await safe(() => $.env.get('TMPDIR'), undefined)) || '/tmp'
  return `${tmp.replace(/\/+$/, '')}/crew-chief-compact`
}

async function prune($, dir, prefix, keep) {
  const entries = await safe(() => $.fs.list(dir), [])
  for (const name of backupsToPrune(entries.map((e) => e.name), prefix, keep)) {
    await safe(() => $.process.run(['rm', '-f', `${dir}/${name}`]), undefined)
  }
}

async function backupSummary($, summary) {
  const dir = `${await dataDir($)}/compact-summaries`
  const path = `${dir}/${backupName('compact', await $.clock.now())}`
  await $.fs.write(path, summary + '\n')
  await safe(() => $.process.run(['chmod', '600', path]), undefined)
  await prune($, dir, 'compact', SUMMARIES_KEPT)
  return path
}

async function transcriptPath($) {
  const home = await safe(() => $.env.get('HOME'), undefined)
  const cwd = await safe(() => $.session.cwd(), undefined)
  const id = await safe(() => $.session.id(), undefined)
  if (!home || !cwd || !id) return undefined
  const path = `${home}/.claude/projects/${projectDirName(cwd)}/${id}.jsonl`
  return (await safe(() => $.fs.exists(path), false)) ? path : undefined
}

async function transcriptLines($) {
  const path = await transcriptPath($)
  if (!path) return undefined
  const r = await safe(() => $.process.run(['wc', '-l', path]), undefined)
  const n = r && r.exitCode === 0 ? Number(r.stdout.trim().split(/\s+/)[0]) : NaN
  return Number.isFinite(n) ? n : undefined
}

// Claude Code appends to the transcript across a compaction, so the lines from before it stay
// searchable (checked live on 2.1.300). If that ever stops being true the first compaction shows it,
// and every later one copies the file first.
async function copyTranscriptIfNeeded($) {
  const kept = await safe(() => $.store.get('transcript_kept'), undefined)
  if (kept !== 'false') return
  const path = await transcriptPath($)
  if (!path) return
  const dir = `${await dataDir($)}/transcripts`
  const copy = `${dir}/${backupName('session', await $.clock.now(), 'jsonl')}`
  await safe(async () => {
    await $.process.run(['mkdir', '-p', dir])
    await $.process.run(['cp', '-p', path, copy])
    await $.process.run(['chmod', '600', copy])
    await prune($, dir, 'session', TRANSCRIPTS_KEPT)
  }, undefined)
}

async function verifyTranscript($, before) {
  if (before === undefined) return
  const after = await transcriptLines($)
  if (after === undefined) return
  const lost = after < before
  await safe(() => $.store.set('transcript_kept', lost ? 'false' : 'true'), undefined)
  if (lost) {
    const lang = await resolveLang($)
    $.ui.toast(t(lang, 'toast_transcript_lost'), { timeoutMs: 12000 })
  }
}

// What the person's files say should survive, checked against the summary Claude Code wrote.
async function pinnedItems($) {
  const h = await findHandoff($)
  if (!h) return { constraints: [], tasks: [] }
  const status = h.status ? await safe(() => $.fs.read(h.status), '') : ''
  const tasks = h.tasks ? await safe(() => $.fs.read(h.tasks), '') : ''
  return { constraints: parseStatus(typeof status === 'string' ? status : '').constraints, tasks: openTasks(typeof tasks === 'string' ? tasks : '') }
}

async function afterCompaction($, result, linesBefore) {
  try {
    const lang = await resolveLang($)
    const summary = result.messages.map((m) => m.text).join('\n')
    const path = await safe(() => backupSummary($, summary), undefined)
    const found = checkSummary(summary, await pinnedItems($))
    const missing = found.missingConstraints.length + found.missingTasks.length
    if (missing > 0) $.ui.toast(t(lang, 'toast_compact_missing', { n: missing }), { timeoutMs: 15000 })
    else $.ui.toast(path ? t(lang, 'toast_compact_done', { path }) : t(lang, 'toast_compact_done_plain'), { timeoutMs: 10000 })
    await verifyTranscript($, linesBefore)
  } catch (err) {
    // The compaction itself succeeded; the extras are best effort.
  }
}

// ---- registration ---------------------------------------------------------------------------

// Called from the mod's session.start hook (a module may register each event only once).
async function compactSessionStart($) {
  resetCompact()
  ck.toolReady = false
  if (await disabled($)) return
  try {
    await $.tool.register({
      name: TOOL_NAME,
      description: TOOL_DESCRIPTION,
      inputSchema: {
        type: 'object',
        properties: {
          phase: { type: 'string', description: 'One line: the phase that was just finished.' },
          next: { type: 'string', description: 'One line: what comes next.' },
        },
      },
      isDeferred: false,
    })
    ck.toolReady = true
  } catch (err) {
    // An older Claude Code, or the name is taken: the fallback question still works.
  }
  try {
    await $.command.register({
      name: 'crew-compact',
      description: t(await resolveLang($), 'cmd_compact_description'),
      argumentHint: '',
    })
  } catch (err) {
    // The name is taken: the tool and the fallback question still work.
  }
}

const clip = (s) => (typeof s === 'string' ? s.replace(/\s+/g, ' ').trim().slice(0, 200) : '')

function registerCompact(on) {
  // The Stop event carries the session's background tasks; the processes among them are remembered for the
  // question and for the summarizer. (Settings-hook events do not reach a mod where an organization manages
  // Claude Code; the list then stays empty and only subagents are waited for.)
  on('classic.Stop', async ($, e, next) => {
    const tasks = Array.isArray(e.background_tasks) ? e.background_tasks : []
    ck.bgTasks = tasks.filter((task) => task && typeof task.command === 'string' && task.command !== '' && !task.agent_type)
    return next(e)
  })

  on('tool.call', { tool: TOOL_MATCH }, async ($, e) => {
    if (e.agentId !== undefined) return { deny: 'Only the main conversation can propose a compaction.' }
    if (!ck.armed || ck.never) return { result: RESULTS.notNeeded }
    if (ck.plan || ck.compacting || ck.asking) return { result: RESULTS.busy }
    // The question waits for the end of this turn (compactTurnComplete): a tool that waited for the
    // person would hold the turn open.
    ck.wantAsk = { phase: clip(e.phase) }
    return { result: RESULTS.noted }
  })

  // Every compaction a person, the engine or another plugin starts passes here. (One this plugin starts
  // does not: the call "runs through every hook but the calling one", so runCompaction passes the brief
  // itself.)
  on('session.compact', async ($, e, next) => {
    if (e.agentId !== undefined || (await focusOff($))) return next(e)
    const before = e.trigger === 'precompute' ? undefined : await transcriptLines($)
    if (e.trigger !== 'precompute') await copyTranscriptIfNeeded($)
    // The engine always sends the transcript with the event; a call without it is passed on without one.
    const input = e.messages === undefined ? (({ messages, ...rest }) => rest)(e) : e
    const result = await next({ ...input, instructions: withFocus(e.instructions, backgroundNote(processHandles())) })
    if (e.trigger !== 'precompute' && result && result.messages) {
      cycleDone()
      await afterCompaction($, result, before)
    }
    return result
  })

  on('command.run', { command: 'crew-compact' }, async ($) => {
    const lang = await resolveLang($)
    if (await disabled($)) return { text: t(lang, 'cmd_compact_off') }
    if (ck.plan || ck.compacting || ck.asking) return { text: t(lang, 'cmd_compact_busy') }
    ck.never = false
    // A command must not hold the turn while the person answers; ask when the loop is free.
    $.clock.after(300, async () => {
      const outcome = await askAndPlan($, {})
      if (outcome === 'approved') requestStateUpdate($)
      else if (outcome === 'subagents') $.ui.toast(t(await resolveLang($), 'ck_wait_agents'), { timeoutMs: 10000 })
    })
    return { text: t(lang, 'cmd_compact_ok') }
  })
}

// ===== tidy-flow =============================================================
// /crew-tidy: what in your context is oversized, repeated, or points at something that is gone.
// Part of the mod in hooks/register.js (Claude Code 2.1.287+).
//
//   /crew-tidy            a report (nothing is changed): the instruction and memory files Claude Code
//                         actually loaded (read from /context), measured against Anthropic's own limits;
//                         paths they mention that no longer exist; lines repeated across files; the
//                         handoff files' size and age; MCP servers and skills by token cost.
//   /crew-tidy archive    moves PROGRESS.md entries older than 60 days to PROGRESS-archive.md. It shows
//                         the count and asks first; the archive is written and read back before the
//                         source is rewritten; nothing is deleted; an entry whose date is unclear stays.
// Files under ~/.claude (your global ones) are only ever reported. Memory files are never rewritten.
const NAMES_SHOWN = 5

function dirOf(path) {
  const at = path.lastIndexOf('/')
  return at > 0 ? path.slice(0, at) : '/'
}

function baseOf(path) {
  return path.slice(path.lastIndexOf('/') + 1)
}

function shown(list) {
  return list.slice(0, NAMES_SHOWN).join(', ') + (list.length > NAMES_SHOWN ? ', …' : '')
}

// The instruction and memory files this session loaded, with their text. The context breakdown names
// exactly those; without it (an older build) the usual project files are looked at instead.
async function loadedFiles($, breakdown, root, cwd) {
  let paths = (breakdown?.memoryFiles ?? []).map((f) => f.path)
  if (paths.length === 0) {
    paths = [`${root}/CLAUDE.md`, `${root}/CLAUDE.local.md`, `${cwd}/CLAUDE.md`]
    const rules = await safe(() => $.fs.list(`${root}/.claude/rules`), [])
    for (const r of rules) if (r.kind === 'file' && r.name.endsWith('.md')) paths.push(`${root}/.claude/rules/${r.name}`)
  }
  const files = []
  for (const path of [...new Set(paths)]) {
    if (!(await safe(() => $.fs.exists(path), false))) continue
    const text = await safe(() => $.fs.read(path), undefined)
    if (typeof text === 'string') files.push({ path, text })
  }
  return files
}

async function pathExists($, ref, root, cwd) {
  const candidates = ref.startsWith('/') ? [ref] : [`${root}/${ref}`, `${cwd}/${ref}`]
  for (const c of candidates) {
    if (await safe(() => $.fs.exists(c.replace(/\/+$/, '')), false)) return true
  }
  return false
}

async function buildTidyReport($) {
  const lang = await resolveLang($)
  const home = await safe(() => $.env.get('HOME'), '')
  const cwd = (await safe(() => $.session.cwd(), '')) || ''
  const root = (await safe(() => $.session.root(), cwd)) || cwd
  const now = await $.clock.now()
  const usage = await safe(() => $.session.usage({ breakdown: 'summary' }), undefined)
  const breakdown = usage?.context?.breakdown
  const findings = []
  const globals = []

  const files = await loadedFiles($, breakdown, root, cwd)
  for (const file of files) {
    const global = isGlobalPath(file.path, home)
    if (global) globals.push(file.path)
    const size = measure(file.text)
    const memoryIndex = baseOf(file.path) === 'MEMORY.md'
    if (memoryIndex) {
      if (size.lines > MEMORY_LINES || size.bytes > MEMORY_BYTES) {
        findings.push(t(lang, 'tidy_memory_long', { path: file.path, lines: size.lines, kb: kb(size.bytes) }))
      }
      const gone = []
      for (const link of memoryIndexLinks(file.text)) {
        if (!(await safe(() => $.fs.exists(`${dirOf(file.path)}/${link}`), false))) gone.push(link)
      }
      if (gone.length > 0) findings.push(t(lang, 'tidy_memory_missing', { path: file.path, n: gone.length, list: shown(gone) }))
      continue
    }
    if (size.lines > INSTRUCTION_LINES) {
      findings.push(t(lang, 'tidy_file_long', { path: file.path, lines: size.lines }))
    }
    const missing = []
    for (const ref of extractPathRefs(file.text)) {
      if (!(await pathExists($, ref, root, cwd))) missing.push(ref)
    }
    if (missing.length > 0) findings.push(t(lang, 'tidy_paths_missing', { path: file.path, n: missing.length, list: shown(missing) }))
  }

  const dupes = findDuplicateLines(files.filter((f) => baseOf(f.path) !== 'MEMORY.md'))
  if (dupes.length > 0) findings.push(t(lang, 'tidy_dupes', { n: dupes.length, sample: dupes[0].line.slice(0, 80) }))

  const handoff = await findHandoff($)
  if (handoff?.status) {
    const text = await safe(() => $.fs.read(handoff.status), '')
    const size = measure(text)
    if (size.bytes > STATUS_BYTES) findings.push(t(lang, 'tidy_status_big', { path: handoff.status, kb: kb(size.bytes) }))
  }
  if (handoff?.progress) {
    const text = await safe(() => $.fs.read(handoff.progress), '')
    const old = splitProgress(text, now, PROGRESS_ARCHIVE_DAYS).count
    if (old > 0) findings.push(t(lang, 'tidy_progress_old', { path: handoff.progress, n: old, days: PROGRESS_ARCHIVE_DAYS }))
  }

  const mcp = summarizeMcp(breakdown?.mcpTools).filter((r) => r.tokens >= MCP_NOTABLE_TOKENS)
  for (const row of mcp) findings.push(t(lang, 'tidy_mcp', { server: row.server, count: row.count, tokens: row.tokens, loaded: row.loaded }))

  const out = [t(lang, 'tidy_head')]
  out.push(...(findings.length > 0 ? findings.map((f) => '- ' + f) : [t(lang, 'tidy_none')]))
  if (breakdown) {
    const top = (breakdown.categories ?? [])
      .filter((c) => c.tokens > 0 && !/free|buffer/i.test(c.name))
      .sort((a, b) => b.tokens - a.tokens)
      .slice(0, NAMES_SHOWN)
      .map((c) => `${c.name} ${c.tokens}`)
    if (top.length > 0) out.push(t(lang, 'tidy_categories', { list: top.join(' · ') }))
    if (breakdown.skills) out.push(t(lang, 'tidy_skills', { n: breakdown.skills.totalSkills, tokens: breakdown.skills.tokens }))
  }
  if (globals.length > 0) out.push(t(lang, 'tidy_global', { list: shown(globals) }))
  return out.join('\n')
}

async function archiveProgress($) {
  const lang = await resolveLang($)
  const handoff = await findHandoff($)
  if (!handoff?.progress) return t(lang, 'tidy_archive_nofile')
  const source = handoff.progress
  const original = await safe(() => $.fs.read(source), undefined)
  if (typeof original !== 'string') return t(lang, 'tidy_archive_failed', { reason: source })
  const now = await $.clock.now()
  const split = splitProgress(original, now, PROGRESS_ARCHIVE_DAYS)
  if (split.count === 0) return t(lang, 'tidy_archive_none', { days: PROGRESS_ARCHIVE_DAYS })
  const archive = source.replace(/\.md$/i, '') + '-archive.md'
  const yes = t(lang, 'tidy_archive_yes')
  const answers = [yes, t(lang, 'tidy_archive_no')]
  let answer
  try {
    answer = await askWithDeadline($, t(lang, 'tidy_archive_ask', { n: split.count, days: PROGRESS_ARCHIVE_DAYS, path: baseOf(source), archive: baseOf(archive) }), answers, answers[1])
  } catch (err) {
    return t(lang, 'tidy_archive_cancelled')
  }
  if (answer !== yes) return t(lang, 'tidy_archive_cancelled')

  try {
    // The file may have changed while the question was open (another session, an editor): look again.
    const current = await $.fs.read(source)
    if (current !== original) return t(lang, 'tidy_archive_changed')
    const existing = (await $.fs.exists(archive)) ? await $.fs.read(archive) : ''
    const header = `# Archived from ${baseOf(source)}\n\nMoved by crew-chief when older than ${PROGRESS_ARCHIVE_DAYS} days. Nothing was deleted.\n\n`
    const next = (existing === '' ? header : existing.replace(/\n*$/, '\n\n')) + split.archived
    await $.fs.write(archive, next)
    const back = await $.fs.read(archive)
    if (!back.includes(split.archived.trim())) throw new Error('the archive did not read back as written')
    // Only now is the source rewritten. If that fails the entries are in both files: nothing is lost.
    await $.fs.write(source, split.keep)
    const kept = await $.fs.read(source)
    if (kept.trim() !== split.keep.trim()) {
      await $.fs.write(source, original)
      throw new Error('the source did not read back as written; it was restored')
    }
  } catch (err) {
    return t(lang, 'tidy_archive_failed', { reason: String(err && err.message ? err.message : err).slice(0, 160) })
  }
  return t(lang, 'tidy_archive_done', { n: split.count, archive })
}

async function tidySessionStart($) {
  try {
    await $.command.register({
      name: 'crew-tidy',
      description: t(await resolveLang($), 'tidy_description'),
      argumentHint: '[archive]',
    })
  } catch (err) {
    // The name is taken: everything else still works.
  }
}

function registerTidy(on) {
  on('command.run', { command: 'crew-tidy' }, async ($, e) => {
    const word = String(e.args || '').trim().toLowerCase()
    if (word === 'archive' || word === 'arşiv' || word === 'arsiv') return { text: await archiveProgress($) }
    return { text: await buildTidyReport($) }
  })
}

// ===== agent-row =============================================================
// crew-chief agent row: one status line with every running subagent's model, effort and tokens. Part of the
// mod in hooks/register.js (Claude Code 2.1.287+).
//
//   scanner haiku-5.5·low 12.4k | implementer opus-5.5·medium 48.1k
//
// The shell panel row (scripts/subagent-row.sh) only reaches a terminal with jq. This line, drawn with
// $.ui.status, also reaches the Desktop app, VS Code and terminals without jq (Windows). The host puts its
// own mark and the plugin's name before it.
//   - model and effort: from each subagent request (turn.step), after the saver's cap was applied;
//   - tokens: the latest request's input + cache + output (its context size), not a running sum;
//   - names and who still runs: $.agent.list() (pending, running, waiting), minus the agents whose turn
//     ended; the line is cleared when none is left.
// CREW_CHIEF_ROW_MOD=auto (default) draws it when a surface is not the terminal, or when the terminal's
// panel row cannot draw (Windows, or no jq: `jq --version` is run once a session to find out);
// `on` always (with a surface), `off` never. Any failure leaves the line alone and the turn untouched.
const ROW_LIVE = ['pending', 'running', 'waiting']
const ROW_RECHECK_MS = 60_000
const ROW_DRAW_DELAY_MS = 50

function freshRow() {
  return {
    agents: new Map(), // agentId -> { model, effort, tokens }
    done: new Set(), // agents whose turn ended (the list can still say running for a moment)
    wanted: undefined,
    checkedAt: undefined,
    hasJq: undefined, // probed once a session, only when it matters
    shown: false, // this module pinned a line
    lastText: undefined,
    drawPending: false,
  }
}

let rowState = freshRow()

async function rowProbeJq($) {
  try {
    const r = await $.process.run(['jq', '--version'], { timeoutMs: 3000 })
    return r.exitCode === 0
  } catch (err) {
    return false // cannot start: not installed
  }
}

// Decided at session start and again at most every ROW_RECHECK_MS (a Desktop or VS Code client can attach).
async function rowCheckWanted($, force) {
  let now
  try {
    now = await $.clock.now()
  } catch (err) {
    return false
  }
  if (!force && rowState.checkedAt !== undefined && now - rowState.checkedAt < ROW_RECHECK_MS) return rowState.wanted === true
  let wanted = false
  try {
    const mode = await $.env.get('CREW_CHIEF_ROW_MOD')
    const surfaces = await $.session.surfaces()
    const platform = platformFromOs(await $.env.get('OS'))
    let hasJq = rowState.hasJq
    if (hasJq === undefined && jqMatters({ mode, surfaces, platform })) {
      hasJq = await rowProbeJq($)
      rowState.hasJq = hasJq
    }
    wanted = rowWanted({ mode, surfaces, platform, hasJq })
  } catch (err) {
    wanted = false
  }
  rowState.wanted = wanted
  rowState.checkedAt = now
  return wanted
}

function rowClear($) {
  if (!rowState.shown) return
  rowState.shown = false
  rowState.lastText = undefined
  try {
    $.ui.status(undefined)
  } catch (err) {
    // Nothing to clear then.
  }
}

function rowAgentName(a) {
  if (typeof a.teammateId === 'string' && a.teammateId !== '') return a.teammateId.replace(/@.*$/, '')
  return a.type || a.description || 'agent'
}

async function rowDraw($) {
  try {
    if (!(await rowCheckWanted($, false))) {
      rowClear($)
      return
    }
    let list
    try {
      list = await $.agent.list()
    } catch (err) {
      list = []
    }
    const rows = []
    for (const a of Array.isArray(list) ? list : []) {
      if (!a || !ROW_LIVE.includes(a.status) || rowState.done.has(a.id)) continue
      const info = rowState.agents.get(a.id) ?? {}
      rows.push({ name: rowAgentName(a), model: info.model, effort: info.effort, tokens: info.tokens })
    }
    const text = formatRow(rows)
    if (text === undefined) {
      rowClear($)
      return
    }
    if (text === rowState.lastText && rowState.shown) return
    $.ui.status(text)
    rowState.shown = true
    rowState.lastText = text
    $.ui.log('crew-chief: agent row = ' + text, { to: 'debug' })
  } catch (err) {
    // A missing line is better than a broken turn.
  }
}

// At most one redraw waits at a time; several requests in a burst draw once.
function rowSchedule($) {
  if (rowState.drawPending) return
  rowState.drawPending = true
  try {
    $.clock.after(ROW_DRAW_DELAY_MS, () => {
      rowState.drawPending = false
      rowDraw($)
    })
  } catch (err) {
    rowState.drawPending = false
  }
}

// Skip the timer while the line is known to be unwanted (rechecked every ROW_RECHECK_MS).
async function rowMaybeSchedule($) {
  if (rowState.wanted === false && !rowState.shown && rowState.checkedAt !== undefined) {
    const now = await $.clock.now()
    if (now - rowState.checkedAt < ROW_RECHECK_MS) return
  }
  rowSchedule($)
}

// Called by the turn.step hook in register.js with the request as it goes out (the saver's cap applied).
async function rowStepStart($, request) {
  try {
    if (request.agentId === undefined) return
    const prev = rowState.agents.get(request.agentId) ?? {}
    rowState.agents.set(request.agentId, { ...prev, model: request.model, effort: request.effort })
    rowState.done.delete(request.agentId)
    await rowMaybeSchedule($)
  } catch (err) {
    // Never in the way of a request.
  }
}

// ...and with its result: the tokens of the agent's latest request.
async function rowStepEnd($, request, result) {
  try {
    if (request.agentId === undefined) return
    const tokens = usageTokens(result?.usage)
    if (tokens === undefined) return
    const prev = rowState.agents.get(request.agentId) ?? {}
    rowState.agents.set(request.agentId, { ...prev, tokens })
    await rowMaybeSchedule($)
  } catch (err) {
    // Never in the way of a request.
  }
}

// The host takes one hook per event from a module (no second unmatched session.start, session.end or
// turn.complete), so register.js calls these from its own hooks.
function rowSessionStart($) {
  rowClear($) // a line left from before /clear or /resume
  rowState = freshRow()
  // Not awaited: `jq --version` must not hold the session's start.
  rowCheckWanted($, true).catch(() => {})
}

function rowSessionEnd($) {
  rowClear($)
  rowState = freshRow()
}

// A subagent's turn ended: off the line now, even if the list still says running. The main turn's end
// is a second chance to clear a line that nothing else redraws.
async function rowTurnComplete($, e) {
  try {
    if (e.agentId !== undefined) rowState.done.add(e.agentId)
    if (rowState.shown || e.agentId !== undefined) await rowMaybeSchedule($)
  } catch (err) {
    // The turn ends either way.
  }
}

// ===== register ==============================================================
// crew-chief saver mod: watches your plan limits and asks whether to turn on a token saver.
//
// What it does (Claude Code 2.1.287 or later; older versions never load this file):
//   - When the 5-hour window crosses 70/80/90 % or the weekly window 50/75/85/90 %, asks once per
//     threshold and window whether to turn the saver on for THIS session. A new session, /clear,
//     and /resume always start with the saver off.
//   - While the saver is on, subagent requests are capped: Opus (and Fable) at medium effort,
//     Sonnet at high (no xhigh or max). Haiku and the main session are never touched.
//   - One toast when the session is 8 hours old.
//   - The compact flow (hooks/compact-flow.mjs): at a phase boundary past 250k tokens it proposes a compaction,
//     asks first, has the handoff files updated, and compacts with a detailed brief so nothing is lost.
//   - /saver [on|off|status]
//   - One status line with every running subagent's model, effort and tokens (hooks/src/agent-row.js), for
//     the Desktop app, VS Code and terminals where the shell panel row cannot draw. CREW_CHIEF_ROW_MOD.
//   - Every question the mod asks has a deadline (hooks/src/ask.js): unanswered after
//     CREW_CHIEF_ASK_TIMEOUT_MIN minutes (default 20), it counts as "not now" / "no" / "cancel".
//   - Once, after the first finished turn of a session where the advisor is off: offers to turn on
//     /advisor (a stronger model Claude can ask at hard moments). It asks first, remembers "not now"
//     for a week and "never" for good, and runs /advisor only after a yes.
// Environment: CREW_CHIEF_SAVER=off silences the saver questions and toasts (not the advisor offer);
// CREW_CHIEF_SAVER_FIVE_HOUR and CREW_CHIEF_SAVER_SEVEN_DAY set the thresholds ("70,80,90");
// CREW_CHIEF_ADVISOR_OFFER=off never offers the advisor; CREW_CHIEF_COMPACT=off turns the compact flow off;
// CREW_CHIEF_LANG=tr|en forces the language of the messages (otherwise: Claude Code's `language`
// setting, then what you have been writing, then the last language seen, then the locale).
// Kept between sessions, in the plugin's store: the language ("tr" or "en") and the answer to the
// advisor offer ("never", "answered", or "later:<time>"). Nothing leaves the machine.
const TURN_STALE_MS = 10 * 60 * 1000
const STEP_STALE_MS = 5 * 60 * 1000

// Per-session state; resetState() puts it back when the session ends, /clear, or /resume.
let saver = false
let snoozed = false
let pending = null
let lastPromptAt = 0
let lastCompleteAt = 0
let lastStepAt = 0
let registered = false
let quiet = false
let ageToasted = false
let capToasted = false
let advisorChecked = false
const seen = new Set()

function resetState() {
  saver = false
  snoozed = false
  open.saver = false
  pending = null
  lastPromptAt = 0
  lastCompleteAt = 0
  lastStepAt = 0
  registered = false
  quiet = false
  ageToasted = false
  capToasted = false
  advisorChecked = false
  resetLang()
  resetResetFlow()
  statsReset()
  seen.clear()
}

async function readConfig($) {
  const off = (await $.env.get('CREW_CHIEF_SAVER')) === 'off'
  const five = parseThresholds(await $.env.get('CREW_CHIEF_SAVER_FIVE_HOUR'), FIVE_HOUR_DEFAULT)
  const week = parseThresholds(await $.env.get('CREW_CHIEF_SAVER_SEVEN_DAY'), SEVEN_DAY_DEFAULT)
  return { off, five, week }
}

// The window that most needs a question, or undefined. Every threshold at or below the current
// percent is marked as seen, so crossing 70 and 80 together asks once, and never again for 70.
function findHit(rateLimits, cfg) {
  let hit
  for (const w of rateLimits) {
    const list = w.kind === 'five_hour' ? cfg.five : w.kind === 'seven_day' ? cfg.week : undefined
    if (list === undefined) continue
    const c = crossing(w.percentUsed, list, seen, w.kind + '|' + w.resetsAt + '|')
    c.crossed.forEach((key) => seen.add(key))
    if (c.top !== undefined && (hit === undefined || w.percentUsed > hit.percent)) {
      hit = { kind: w.kind, percent: w.percentUsed, resetsAt: w.resetsAt }
    }
  }
  return hit
}

async function ageNotice($, usage) {
  const now = await $.clock.now()
  if (!ageToasted && typeof usage.startedAt === 'number' && now - usage.startedAt >= SESSION_AGE_TOAST_MS) {
    ageToasted = true
    const lang = await resolveLang($)
    $.ui.toast(t(lang, 'toast_age', { duration: formatDuration(now - usage.startedAt, unitsFor(lang)) }), { timeoutMs: 12000 })
  }
}

async function askUser($, hit) {
  open.saver = true
  try {
    const lang = await resolveLang($)
    const answers = [t(lang, 'answer_on'), t(lang, 'answer_not_now'), t(lang, 'answer_never')]
    const now = await $.clock.now()
    const left = hit.resetsAt ? Date.parse(hit.resetsAt) - now : 0
    const reset = left > 0 ? t(lang, 'reset_in', { duration: formatDuration(left, unitsFor(lang)) }) : ''
    const answer = await askWithDeadline(
      $,
      t(lang, 'ask', { window: windowName(lang, hit.kind), percent: hit.percent, reset }),
      answers,
      answers[1],
    )
    if (answer === answers[0]) {
      saver = true
      $.ui.toast(t(lang, 'toast_saver_on'), { timeoutMs: 8000 })
    } else if (answer === answers[2]) {
      snoozed = true
    }
  } catch (err) {
    // Dismissed, or a run with nobody to ask: treat it as "not now".
  } finally {
    open.saver = false
  }
}

// Not awaited on purpose: the hook that calls this must not wait for the person to answer.
function launchAsk($) {
  const hit = pending
  if (hit !== null && !open.saver && !open.compact && !open.reset) {
    pending = null
    askUser($, hit)
  }
}

async function evaluate($) {
  const cfg = await readConfig($)
  quiet = cfg.off
  if (cfg.off) return
  const usage = await $.session.usage()
  await ageNotice($, usage)
  if (saver || snoozed || open.saver) return
  const hit = findHit(usage.rateLimits, cfg)
  if (hit !== undefined) pending = hit
}

async function onCloudProvider($) {
  // The advisor is a server tool of the Anthropic API; these routes do not have it.
  const flags = [
    await $.env.get('CLAUDE_CODE_USE_BEDROCK'),
    await $.env.get('CLAUDE_CODE_USE_VERTEX'),
    await $.env.get('CLAUDE_CODE_USE_FOUNDRY'),
    await $.env.get('CLAUDE_CODE_USE_ANTHROPIC_AWS'),
    await $.env.get('CLAUDE_CODE_USE_ANTHROPIC_GOOGLE_CLOUD'),
  ]
  return flags.some(isEnvFlag)
}

async function rememberAdvisorAnswer($, value) {
  try {
    await $.store.set('advisor', value)
  } catch (err) {
    // Not remembered: the offer may come back next session.
  }
}

// The command writes the setting a moment after it returns, so look a few times before giving up.
async function advisorIsSet($) {
  for (let attempt = 0; attempt < 5; attempt++) {
    const settings = await $.settings.read()
    if (settings.advisorModel) return true
    if (attempt < 4) await $.clock.sleep(400)
  }
  return false
}

// Runs outside the hook that scheduled it (a hook the turn waits on may not run commands). Only a
// result that is visible in the settings counts as "answered"; a refusal (a policy, Fable credits)
// is remembered as "never" so the offer does not repeat a command that cannot work.
async function enableAdvisor($, advisor, lang) {
  try {
    await $.command.run({ command: 'advisor', args: advisor })
    if (!(await advisorIsSet($))) throw new Error('the advisor setting did not change')
    await rememberAdvisorAnswer($, 'answered')
    $.ui.toast(t(lang, 'advisor_toast_on', { advisor: t(lang, 'model_' + advisor) }), { timeoutMs: 8000 })
  } catch (err) {
    await rememberAdvisorAnswer($, 'never')
    $.ui.toast(t(lang, 'advisor_toast_failed'), { timeoutMs: 12000 })
  }
}

// Offers the advisor once. Every gate that says "not for this person or this setup" returns
// quietly; a dismissed dialog (or a run with nobody to ask) leaves no trace, so it can come back.
async function offerAdvisor($) {
  if (open.saver || open.compact || open.reset) return
  open.saver = true
  try {
    if ((await $.env.get('CREW_CHIEF_ADVISOR_OFFER')) === 'off') return
    if (isEnvFlag(await $.env.get('CLAUDE_CODE_DISABLE_ADVISOR_TOOL'))) return
    if (await onCloudProvider($)) return
    const settings = await $.settings.read()
    if (settings.advisorModel) return
    const commands = await $.command.list()
    if (!commands.some((c) => c.name === 'advisor')) return
    const plan = advisorPlan(await $.session.model())
    if (plan === undefined) return
    let stored
    try {
      stored = await $.store.get('advisor')
    } catch (err) {
      // No store: treated as never asked.
    }
    const now = await $.clock.now()
    if (!advisorOfferAllowed(stored, now)) return
    const lang = await resolveLang($)
    const answers = [t(lang, 'advisor_answer_on'), t(lang, 'advisor_answer_later'), t(lang, 'advisor_answer_never')]
    const main = t(lang, 'model_' + plan.family)
    const advisor = t(lang, 'model_' + plan.advisor)
    let answer
    try {
      // Unanswered: "remind me in a week", the same as clicking it.
      answer = await askWithDeadline($, t(lang, plan.kind === 'second' ? 'advisor_ask_second' : 'advisor_ask_standard', { main, advisor }), answers, answers[1])
    } catch (err) {
      return
    }
    if (answer === answers[0]) {
      $.clock.after(300, () => enableAdvisor($, plan.advisor, lang))
    } else if (answer === answers[1]) {
      await rememberAdvisorAnswer($, 'later:' + (now + ADVISOR_LATER_MS))
    } else if (answer === answers[2]) {
      await rememberAdvisorAnswer($, 'never')
    }
  } catch (err) {
    // Anything unexpected: stay quiet rather than get in the way.
  } finally {
    open.saver = false
  }
}

// A main-thread turn is running when a prompt or a model request went out after the last finished
// turn. Model requests count too: a prompt queued while the previous turn ran, a turn longer than
// TURN_STALE_MS, and a turn started by a background notification never pass through prompt.submit
// at the right time. Both marks go stale so a lost turn.complete cannot block questions for good.
async function turnInFlight($) {
  const now = await $.clock.now()
  const byPrompt = lastPromptAt > lastCompleteAt && now - lastPromptAt < TURN_STALE_MS
  const byStep = lastStepAt > lastCompleteAt && now - lastStepAt < STEP_STALE_MS
  return byPrompt || byStep
}

async function statusText($) {
  const lang = await resolveLang($)
  const units = unitsFor(lang)
  const usage = await $.session.usage()
  const now = await $.clock.now()
  const parts = [t(lang, saver ? 'status_on' : 'status_off') + (snoozed ? t(lang, 'status_snoozed') : '')]
  for (const w of usage.rateLimits) {
    const left = w.resetsAt ? Date.parse(w.resetsAt) - now : 0
    parts.push(windowName(lang, w.kind) + ' ' + t(lang, 'percent', { n: w.percentUsed }) + (left > 0 ? t(lang, 'status_resets', { duration: formatDuration(left, units) }) : ''))
  }
  if (usage.rateLimits.length === 0) parts.push(t(lang, 'status_no_data'))
  if (usage.context && typeof usage.context.tokens === 'number') parts.push(t(lang, 'status_context', { tokens: tokensLabel(usage.context.tokens) }))
  return parts.join(' · ')
}

// True when /saver is a registered command and is not a built-in. The host only routes command.run to
// the plugin that registered the name, so a listed /saver that this module did not register itself
// is ours from an earlier registration.
async function ownsSaver($) {
  try {
    const commands = await $.command.list()
    return commands.some((c) => c.name === 'saver' && c.source !== 'builtin')
  } catch (err) {
    return false
  }
}

export function register(on) {
  on('session.start', async ($, e, next) => {
    resetState()
    const result = await next(e)
    try {
      await $.command.register({
        name: 'saver',
        description: t(await resolveLang($), 'cmd_description'),
        argumentHint: '[on|off|status]',
      })
      registered = true
    } catch (err) {
      // The name is taken: by a built-in or another plugin's command (leave it alone), or by this
      // plugin's own earlier registration (/clear, /resume run session.start again), see ownsSaver.
      registered = await ownsSaver($)
    }
    await compactSessionStart($)
    await tidySessionStart($)
    await statsSessionStart($)
    rowSessionStart($)
    return result
  })

  on('session.end', async ($, e, next) => {
    resetState()
    resetCompact()
    rowSessionEnd($)
    return next(e)
  })

  on('prompt.submit', async ($, e, next) => {
    lastPromptAt = await $.clock.now()
    compactNoteActivity()
    // Only what the person types counts: task notifications, peer sessions, schedules, and other
    // plugins also come through prompt.submit, and their text is usually English.
    const kind = e.origin ? e.origin.kind : undefined
    const verdict = kind === undefined || kind === 'composer' || kind === 'bridge' ? classifyText(e.text) : undefined
    if (verdict !== undefined) {
      addLanguageVote(verdict)
    }
    if (kind === undefined || kind === 'composer' || kind === 'bridge') {
      resetNotePrompt(lastPromptAt)
      await cacheOnPrompt($)
    }
    const nudge = await compactNudge($)
    return next(nudge === undefined ? e : { ...e, context: [...(e.context ?? []), nudge] })
  })

  on('session.measure', async ($, e, next) => {
    await compactUpdate($, e)
    await resetOnUsage($, e)
    await evaluate($)
    if (pending !== null && !(await turnInFlight($))) launchAsk($)
    return next(e)
  })

  // The measure event can arrive mid-turn or not at all; a finished main turn is the safe moment
  // to ask, and a second chance to notice the limits.
  on('turn.complete', async ($, e, next) => {
    await rowTurnComplete($, e)
    if (e.agentId === undefined) {
      lastCompleteAt = await $.clock.now()
      const usage = await $.session.usage()
      await compactTurnComplete($, usage, e.reason)
      await resetOnUsage($, usage)
      await evaluate($)
      launchAsk($)
      if (e.reason === 'answer' && !advisorChecked && pending === null && !open.saver) {
        advisorChecked = true
        offerAdvisor($)
      }
    }
    return next(e)
  })

  on('turn.step', async function* ($, e, next) {
    if (e.agentId === undefined) {
      lastStepAt = await $.clock.now()
      compactNoteActivity()
    }
    await statsStepStart($, e)
    // Debug log only (claude --debug-file): what the host hands this hook for a subagent request.
    if (e.agentId !== undefined) {
      $.ui.log('saver: step agent=' + e.agentId + ' model=' + e.model + ' effort=' + String(e.effort) + ' saver=' + saver, { to: 'debug' })
    }
    let request = e
    if (saver && e.agentId !== undefined) {
      const cap = capEffort(e.model, e.effort)
      if (cap.capped) {
        if (!capToasted && !quiet) {
          capToasted = true
          const lang = await resolveLang($)
          const model = t(lang, cap.tier === 'heavy' ? 'model_heavy' : 'model_sonnet')
          $.ui.toast(t(lang, 'toast_cap', { model, from: cap.from, to: cap.effort }), { timeoutMs: 6000 })
        }
        $.ui.log('saver: subagent ' + e.agentId + ' on ' + e.model + ' effort ' + cap.from + ' -> ' + cap.effort, { to: 'debug' })
        request = { ...e, effort: cap.effort }
      }
    }
    await rowStepStart($, request)
    const result = yield* next(request)
    await statsStepEnd($, e, result)
    await rowStepEnd($, request, result)
    return result
  })

  // While the saver is on, an Agent call for one of the Opus agents carries effort medium. The
  // turn.step cap below stays as the second line. Any failure here leaves the call as it was.
  on('tool.call', async ($, e, next) => {
    let request = e
    try {
      const effort = saver && e.tool === 'Agent' ? agentCallEffort(e) : undefined
      if (effort !== undefined) {
        $.ui.log('saver: Agent call ' + String(e.subagent_type) + ' effort ' + String(e.effort) + ' -> ' + effort, { to: 'debug' })
        request = { ...e, effort }
      }
    } catch (err) {
      request = e
    }
    return next(request)
  })

  on('command.run', { command: 'saver' }, async ($, e, next) => {
    // The module can be loaded again (/reload-plugins, an update) without a new session.start, which
    // leaves `registered` false while the host still has our command: look it up before refusing.
    if (!registered) registered = await ownsSaver($)
    if (!registered) return next(e)
    const word = String(e.args || '').trim().toLowerCase()
    const lang = await resolveLang($)
    if (word === 'on') {
      saver = true
      snoozed = false
      return { text: t(lang, 'cmd_on') }
    }
    if (word === 'off') {
      saver = false
      snoozed = true
      return { text: t(lang, 'cmd_off') }
    }
    if (word === '' || word === 'status') return { text: await statusText($) }
    return { text: t(lang, 'cmd_usage') }
  })

  registerAsk(on)
  registerCompact(on)
  registerReset(on)
  registerTidy(on)
  registerStats(on)
}
